void obd_ii_o2_transition_activity_counter
               (ushort o2_voltage,ushort *o2_activity_state_flags,short *o2_activity_timer,
               ushort *o2_voltage_max,ushort *o2_voltage_min,int *o2_rich_transition_accum,
               int *o2_lean_transition_accum,byte *o2_rich_transition_count,
               byte *o2_lean_transition_count,byte *o2_leanrich_flags,byte *o2_rich_duration_counter
               ,byte *o2_lean_duration_counter)

{
  if ((*o2_activity_state_flags & 1) == 0) {
    *o2_leanrich_flags = *o2_leanrich_flags & 0x3f;
    *o2_lean_duration_counter = 0;
    *o2_rich_duration_counter = 0;
  }
  else if (*o2_activity_timer == 0) {
    *o2_activity_state_flags = *o2_activity_state_flags | 0x400;
    if (((*o2_activity_state_flags & 4) == 0) && ((*o2_activity_state_flags & 2) == 0)) {
      if ((*o2_lean_transition_count == 0) || (*o2_rich_transition_count == 0)) {
        *o2_lean_transition_accum = 0;
        *o2_rich_transition_accum = 0;
        *o2_activity_state_flags = *o2_activity_state_flags | 0x1000;
      }
      *o2_activity_state_flags = *o2_activity_state_flags | 2;
      *o2_leanrich_flags = *o2_leanrich_flags & 0x3f;
      *o2_lean_duration_counter = 0;
      *o2_rich_duration_counter = 0;
    }
  }
  else {
    *o2_activity_timer = *o2_activity_timer + -1;
    if ((*o2_activity_state_flags & 4) == 0) {
      if (*o2_voltage_max < o2_voltage) {
        *o2_voltage_max = o2_voltage;
      }
      else if (o2_voltage < *o2_voltage_min) {
        *o2_voltage_min = o2_voltage;
      }
      if ((*o2_leanrich_flags & 2) != 0) {
        if (((*o2_leanrich_flags & 0x40) != 0) &&
           (*o2_lean_transition_accum = *o2_lean_transition_accum + (uint)*o2_lean_duration_counter,
           *o2_lean_transition_count != 0xff)) {
          *o2_lean_transition_count = *o2_lean_transition_count + 1;
        }
        *o2_leanrich_flags = *o2_leanrich_flags & 0x3f;
        *o2_lean_duration_counter = 0;
        *o2_rich_duration_counter = 0;
      }
      if ((*o2_leanrich_flags & 4) != 0) {
        if (((*o2_leanrich_flags & 0x80) != 0) &&
           (*o2_rich_transition_accum = *o2_rich_transition_accum + (uint)*o2_rich_duration_counter,
           *o2_rich_transition_count != 0xff)) {
          *o2_rich_transition_count = *o2_rich_transition_count + 1;
        }
        *o2_leanrich_flags = *o2_leanrich_flags & 0x3f;
        *o2_lean_duration_counter = 0;
        *o2_rich_duration_counter = 0;
      }
      if ((*o2_leanrich_flags & 8) != 0) {
        if (*o2_lean_duration_counter != 0xff) {
          *o2_lean_duration_counter = *o2_lean_duration_counter + 1;
        }
        *o2_rich_duration_counter = 0;
      }
      if ((*o2_leanrich_flags & 1) != 0) {
        if (*o2_rich_duration_counter != 0xff) {
          *o2_rich_duration_counter = *o2_rich_duration_counter + 1;
        }
        *o2_lean_duration_counter = 0;
      }
      if ((CAL_obd_ii_o2_transition_count <= *o2_lean_transition_count) &&
         (CAL_obd_ii_o2_transition_count <= *o2_rich_transition_count)) {
        *o2_activity_state_flags = *o2_activity_state_flags | 2;
      }
    }
  }
  return;
}



