void obd_ii_thermostat_check(void)

{
  uint32_t uVar1;
  uint8_t uVar2;
  u8_count uVar3;
  ulonglong unaff_r31;
  
  if (((engine_operating_state_flags & 8) == 0) || (car_speed_u8 != '\0')) {
    thermostat_warmup_load_weight =
         lookup_2D_uint8_interpolated
                   ('\b',load_mass_per_stroke,CAL_cooling_thermostat_warmup_load_factor,
                    CAL_cooling_thermostat_warmup_load_factor_X_load);
  }
  else {
    thermostat_warmup_load_weight = 0xff;
  }
  uVar2 = '\x01';
  if (CAL_obd_ii_P0128_iat_min < temp_engine_air) {
    uVar2 = obd_ii_P0128_iat_too_cold_latch;
  }
  obd_ii_P0128_iat_too_cold_latch = uVar2;
  if ((((((CAL_obd_ii_P0128 & 7) != 0) && ((engine_state_failure_flags & 2) == 0)) &&
       (CAL_obd_ii_P0128_start_coolant_min < coolant_temp_engine_stopped)) &&
      ((coolant_temp_engine_stopped < CAL_obd_ii_P0128_start_coolant_max &&
       ((LEA_obd_ii_P0128_dtc_state & 8) == 0)))) && (uVar2 == '\0')) {
    uVar1 = obd_ii_P0128_lowspeed_seconds;
    if ((car_speed_u8 < CAL_obd_ii_P0128_lowspeed_threshold) &&
       (uVar1 = obd_ii_P0128_lowspeed_seconds + 1, engine_speed_16bit == 0)) {
      uVar1 = obd_ii_P0128_lowspeed_seconds;
    }
    obd_ii_P0128_lowspeed_seconds = uVar1;
    if (((uint)thermostat_diag_maf_threshold_ips < thermostat_warmup_air_mass >> 0x10) &&
       (coolant_temp < CAL_cooling_thermostat_open)) {
      if (obd_ii_P0128_lowspeed_seconds != 0) {
        if ((ulonglong)(runtime_since_start >> 1) / (ulonglong)obd_ii_P0128_lowspeed_seconds < 0x100
           ) {
          unaff_r31 = (ulonglong)(runtime_since_start >> 1) /
                      (ulonglong)obd_ii_P0128_lowspeed_seconds & 0xff;
        }
        else {
          unaff_r31 = 0xff;
        }
      }
      if ((ulonglong)CAL_obd_ii_P0128_runtime_to_lowspeed_ratio_min < (unaff_r31 & 0xff)) {
        uVar3 = obd_ii_p0128_health + 0xff;
        if (obd_ii_p0128_health == '\0') {
          uVar3 = obd_ii_p0128_health;
        }
        obd_ii_p0128_health = uVar3;
        if (uVar3 == '\0') {
          obd_ii_monitor_fail_transition
                    (&CAL_obd_ii_P0128,&LEA_obd_ii_P0128_dtc_state,&LEA_obd_ii_P0128_fail_counter,
                     &LEA_obd_ii_P0128_pass_counter,0x128,0);
        }
      }
    }
    else if (CAL_cooling_thermostat_open <= coolant_temp) {
      obd_ii_monitor_pass(&CAL_obd_ii_P0128,&LEA_obd_ii_P0128_dtc_state);
      if (obd_ii_p0128_health < CAL_obd_ii_P0128_fail_count) {
        obd_ii_p0128_health = obd_ii_p0128_health + '\x01';
      }
    }
  }
  return;
}



