void trans_fluid_pump_enable(void)

{
  if ((trans_pump_condition_flags & 1) == 0) {
    siu_gpdo[0x7c] = '\x01';
    trans_pump_condition_flags = trans_pump_condition_flags | 1;
  }
  return;
}



void trans_fluid_pump_disable(void)

{
  if ((trans_pump_condition_flags & 1) != 0) {
    siu_gpdo[0x7c] = '\0';
    trans_pump_condition_flags = trans_pump_condition_flags & 0xfe;
  }
  return;
}



//   Control Logic Map:
//   - Zone 1: zone1_min < temp ≤ zone1_max → Enable pump (warmup circulation)
//   - Zone 2a: zone2_threshold < temp < optimal_min → Enable pump (active cooling needed)
//   - Zone 2b: optimal_min ≤ temp < optimal_max → Disable pump (ideal operating temp)
//   - Zone 2c: temp ≥ optimal_max → Enable pump unless temp < overheat_hysteresis (aggressive
// cooling)
//   - Cold: temp ≤ zone2_threshold → Disable pump (too cold)
// 

void trans_cooler_control(void)

{
  byte bVar1;
  
  obd_ii_trans_fluid_diagnostic();
  if (car_speed_u8 < CAL_trans_pump_carspeed_enable[0]) {
    bVar1 = trans_pump_condition_flags & 0b11110111;
    if (CAL_trans_pump_carspeed_enable[1] < car_speed_u8) {
      bVar1 = trans_pump_condition_flags;
    }
  }
  else {
    bVar1 = trans_pump_condition_flags | 8;
  }
  trans_pump_condition_flags = bVar1;
  if ((CAL_trans_pump_warmup_min < trans_fluid_temp_u8) &&
     (trans_fluid_temp_u8 <= CAL_trans_pump_warmup_max)) {
    bVar1 = trans_pump_condition_flags | 2;
  }
  else if (CAL_trans_pump_cold_cutoff < trans_fluid_temp_u8) {
    if ((trans_fluid_temp_u8 < CAL_trans_pump_no_cool_min) ||
       (CAL_trans_pump_no_cool_max <= trans_fluid_temp_u8)) {
      bVar1 = trans_pump_condition_flags | 2;
      if (trans_fluid_temp_u8 < CAL_trans_pump_cool_off) {
        bVar1 = trans_pump_condition_flags;
      }
    }
    else {
      bVar1 = trans_pump_condition_flags & 0xfd;
    }
  }
  else {
    bVar1 = trans_pump_condition_flags & 0xfd;
  }
  trans_pump_condition_flags = bVar1;
  if ((CAL_trans_pump_ect_on_min < coolant_temp) && (coolant_temp <= CAL_trans_pump_ect_on_max)) {
    trans_pump_condition_flags = trans_pump_condition_flags | 4;
  }
  else if ((coolant_temp <= CAL_trans_pump_ect_off_min) ||
          (CAL_trans_pump_ect_off_max < coolant_temp)) {
    trans_pump_condition_flags = trans_pump_condition_flags & 0xfb;
  }
  if ((obd_ii_2f_trans_pump_requested & 1) == 0) {
    if (trans_fluid_pump_mode == '\0') {
      if ((trans_pump_condition_flags & 0xe) == 0xe) {
        trans_fluid_pump_enable();
      }
      else {
        trans_fluid_pump_disable();
      }
    }
    else if (trans_fluid_pump_mode == '\x01') {
      trans_fluid_pump_enable();
    }
    else if (trans_fluid_pump_mode == '\x02') {
      trans_fluid_pump_disable();
    }
  }
  else if ((obd_ii_2f_trans_pump_state & 1) == 0) {
    trans_fluid_pump_disable();
  }
  else {
    trans_fluid_pump_enable();
  }
  return;
}



void obd_ii_trans_fluid_diagnostic(void)

{
  if ((trans_pump_condition_flags & 1) == 0) {
                    // pump off
    trans_fluid_pump_timer[1] = 0;
    trans_fluid_pump_timer[0] = 0;
    trans_fluid_last = trans_fluid_temp_u8;
  }
  else {
    if (trans_fluid_pump_timer[1] != 0xffff) {
      trans_fluid_pump_timer[1] = trans_fluid_pump_timer[1] + 1;
    }
    if ((((car_speed_u8 < CAL_obd_ii_trans_fluid_speed_window[0]) &&
         (CAL_obd_ii_trans_fluid_speed_window[1] < car_speed_u8)) &&
        (trans_fluid_temp_u8 < CAL_obd_ii_trans_fluid_temp_window[0])) &&
       ((CAL_obd_ii_trans_fluid_temp_window[1] < trans_fluid_temp_u8 &&
        ((trans_pump_condition_flags & 0x10) == 0)))) {
      if (trans_fluid_pump_timer[0] != 0xffff) {
        trans_fluid_pump_timer[0] = trans_fluid_pump_timer[0] + 1;
      }
    }
    else {
      trans_fluid_pump_timer[0] = 0;
      trans_fluid_last = trans_fluid_temp_u8;
    }
  }
  if (((CAL_obd_ii_P0712 & 7) != 0) && (engine_is_running)) {
    if (trans_temp_voltage < CAL_trans_temp_voltage_threshold[1]) {
      obd_ii_p0712_fail_ticks = obd_ii_p0712_fail_ticks + 1;
      if ((((int)(short)obd_ii_monitor_debounce_ticks <= (int)(uint)obd_ii_p0712_fail_ticks) &&
          (obd_ii_p0712_fail_ticks = 0, obd_ii_p0712_health != '\0')) &&
         (obd_ii_p0712_health = obd_ii_p0712_health + 0xff, obd_ii_p0712_health == '\0')) {
        obd_ii_monitor_fail_transition
                  (&CAL_obd_ii_P0712,&LEA_obd_ii_P0712_dtc_state,&LEA_obd_ii_P0712_fail_counter,
                   &LEA_obd_ii_P0712_pass_counter,0x712,0);
      }
    }
    else {
      obd_ii_p0712_fail_ticks = 0;
      obd_ii_monitor_pass(&CAL_obd_ii_P0712,&LEA_obd_ii_P0712_dtc_state);
      if (obd_ii_p0712_health < CAL_obd_ii_P0712_debounce_count) {
        obd_ii_p0712_health = obd_ii_p0712_health + '\x01';
      }
    }
  }
  if (((CAL_obd_ii_P0713 & 7) != 0) && (engine_is_running != false)) {
    if (CAL_trans_temp_voltage_threshold[0] < trans_temp_voltage) {
      obd_ii_p0713_fail_ticks = obd_ii_p0713_fail_ticks + 1;
      if ((((int)(short)obd_ii_monitor_debounce_ticks <= (int)(uint)obd_ii_p0713_fail_ticks) &&
          (obd_ii_p0713_fail_ticks = 0, obd_ii_p0713_health != '\0')) &&
         (obd_ii_p0713_health = obd_ii_p0713_health + 0xff, obd_ii_p0713_health == '\0')) {
        obd_ii_monitor_fail_transition
                  (&CAL_obd_ii_P0713,&LEA_obd_ii_P0713_dtc_state,&LEA_obd_ii_P0713_fail_counter,
                   &LEA_obd_ii_P0713_pass_counter,0x713,0);
      }
    }
    else {
      obd_ii_p0713_fail_ticks = 0;
      obd_ii_monitor_pass(&CAL_obd_ii_P0713,&LEA_obd_ii_P0713_dtc_state);
      if (obd_ii_p0713_health < CAL_obd_ii_P0713_debounce_count) {
        obd_ii_p0713_health = obd_ii_p0713_health + '\x01';
      }
    }
  }
  if ((((((CAL_obd_ii_P2797 & 7) != 0) && (engine_is_running != false)) &&
       ((ignition_on_flags & 1) != 0)) &&
      ((CAL_obd_ii_trans_fluid_pump_time_min < trans_fluid_pump_timer[0] &&
       ((trans_pump_condition_flags & 0x10) == 0)))) &&
     (((LEA_obd_ii_P0712_dtc_state & 4) == 0 &&
      (((LEA_obd_ii_P0713_dtc_state & 4) == 0 &&
       (trans_pump_condition_flags = trans_pump_condition_flags | 0x10,
       trans_fluid_last < trans_fluid_temp_u8)))))) {
    if ((int)((uint)trans_fluid_temp_u8 - (uint)trans_fluid_last) <
        (int)(uint)CAL_trans_fluid_P2797_threshold) {
      obd_ii_monitor_fail_transition
                (&CAL_obd_ii_P2797,&LEA_obd_ii_P2797_dtc_state,&LEA_obd_ii_P2797_fail_counter,
                 &LEA_obd_ii_P2797_pass_counter,0x2797,0);
    }
    else if ((int)(uint)CAL_trans_fluid_P2797_threshold <=
             (int)((uint)trans_fluid_temp_u8 - (uint)trans_fluid_last)) {
      obd_ii_monitor_pass(&CAL_obd_ii_P2797,&LEA_obd_ii_P2797_dtc_state);
    }
  }
  if ((CAL_obd_ii_P0897 & 7) != 0) {
    if (((CAL_obd_ii_trans_fluid_temp_high < trans_fluid_temp_u8) &&
        ((LEA_obd_ii_P0713_dtc_state & 4) == 0)) && ((LEA_obd_ii_P0713_dtc_state & 4) == 0)) {
      obd_ii_p0897_fail_ticks = obd_ii_p0897_fail_ticks + 1;
      if (((CAL_obd_ii_P0897_debounce <= obd_ii_p0897_fail_ticks) &&
          (obd_ii_p0897_fail_ticks = 0, obd_ii_p0897_health != '\0')) &&
         (obd_ii_p0897_health = obd_ii_p0897_health + 0xff, obd_ii_p0897_health == '\0')) {
        obd_ii_monitor_fail_transition
                  (&CAL_obd_ii_P0897,&LEA_obd_ii_P0897_dtc_state,&LEA_obd_ii_P0897_fail_counter,
                   &LEA_obd_ii_P0897_pass_counter,0x897,0);
      }
    }
    else if (obd_ii_p0897_fail_ticks == 0) {
      if (obd_ii_p0897_health < CAL_obd_ii_P0897_debounce_count) {
        obd_ii_p0897_health = obd_ii_p0897_health + '\x01';
        obd_ii_p0897_fail_ticks = (u16_count)CAL_obd_ii_P0897_debounce;
      }
      else {
        obd_ii_monitor_pass(&CAL_obd_ii_P0897,&LEA_obd_ii_P0897_dtc_state);
      }
    }
    else {
      obd_ii_p0897_fail_ticks = obd_ii_p0897_fail_ticks - 1;
    }
  }
  return;
}



