       libc_abs((longlong)(short)wheel_speeds.LR - (longlong)(short)wheel_speeds.RR);
  dpm_rear_lr_speed_diff = (u16_speed_1_100kph)_rear_speed_diff_abs;
  _front_speed_diff_abs =
       libc_abs((longlong)(short)wheel_speeds.LF - (longlong)(short)wheel_speeds.RF);
  dpm_front_lr_speed_diff = (u16_speed_1_100kph)_front_speed_diff_abs;
  dpm_max_lr_speed_diff = dpm_front_lr_speed_diff;
  if (dpm_front_lr_speed_diff < dpm_rear_lr_speed_diff) {
    dpm_max_lr_speed_diff = dpm_rear_lr_speed_diff;
  }
  if ((dpm_front_axle_speed_max < dpm_rear_axle_speed_max) && (dpm_front_axle_speed_max != 0)) {
    _calculated_slip = ((uint)dpm_rear_axle_speed_max * 800) / (uint)dpm_front_axle_speed_max - 800;
    if (_calculated_slip < 0x10000) {
      dpm_slip = (u16_slip_1_8pct)_calculated_slip;
    }
    else {
      dpm_slip = 0xffff;
    }
  }
  else {
    dpm_slip = 0;
  }
                    // ┌─────┬────────┬──────────────┬──────────────────────────────────────────────────────┐
                    // │Bit │  Mask │     Name   │               Meaning
                    // │
                    // ├─────┼────────┼──────────────┼──────────────────────────────────────────────────────┤
                    // │ 0   │ 0x0001 │ ACTIVE   │ Torque is being cut this tick
                    // │
                    // ├─────┼────────┼──────────────┼──────────────────────────────────────────────────────┤
                    // │ 1   │ 0x0002 │ ENABLED  │ In an intervention episode (armed to cut)
                    // │
                    // ├─────┼────────┼──────────────┼──────────────────────────────────────────────────────┤
                    // │ 2   │ 0x0004 │ DIRECT   │ Direct mode — cornering detected via
                    // L-R speed split │
                    // ├─────┼────────┼──────────────┼──────────────────────────────────────────────────────┤
                    // │ 3   │ 0x0008 │ SLIP_VALID   │ Slip calc produced a usable value
                    // │
                    // ├─────┼────────┼──────────────┼──────────────────────────────────────────────────────┤
                    // │ 4   │ 0x0010 │ SYS_ENABLED  │ Driver has DPM switched on
                    // │
                    // ├─────┼────────┼──────────────┼──────────────────────────────────────────────────────┤
